package com.affinity.api;
import java.util.*;
public record RequestOptions(String practiceId,String idempotencyKey,String organizationId,String actorId,String actorType){public static Builder builder(){return new Builder();}Map<String,String> headers(){Map<String,String> h=new HashMap<>();if(organizationId!=null)h.put("organizationId",organizationId);if(actorId!=null)h.put("actorId",actorId);if(actorType!=null)h.put("actorType",actorType);return h;}public static final class Builder{private String practiceId,idempotencyKey,organizationId,actorId,actorType;public Builder practiceId(String value){this.practiceId=value;return this;}public Builder idempotencyKey(String value){this.idempotencyKey=value;return this;}public Builder organizationId(String value){this.organizationId=value;return this;}public Builder actorId(String value){this.actorId=value;return this;}public Builder actorType(String value){this.actorType=value;return this;}public RequestOptions build(){return new RequestOptions(practiceId,idempotencyKey,organizationId,actorId,actorType);}}}